using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata for known types
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for Person: {personInfo.Type.Name}");

// Use it to serialize
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Create options with NO resolver so nothing is resolvable
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo on empty resolver => found: {found}, info: {info?.Type.Name ?? "(null)"}");

// And confirm it works positively with the real resolver
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info2);
Console.WriteLine($"TryGetTypeInfo on real resolver  => found: {found2}, info: {info2?.Type.Name ?? "(null)"}");

record Person(string Name, int Age);

